const host = "princess.kanish.fun";
const revision = "85e42f07b5ecdcb566424a38ef9dad6c9bd3a9f7";
const common = {"x-content-type-options":"nosniff","x-robots-tag":"noindex","referrer-policy":"no-referrer"};

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (!["GET","HEAD"].includes(request.method)) {
      return new Response("Method not allowed",{status:405,headers:{allow:"GET, HEAD"}});
    }
    if (["kanish.fun","www.kanish.fun"].includes(url.hostname) && ["/","/princess","/princess/"].includes(url.pathname)) {
      return Response.redirect("https://" + host + "/" + url.search,302);
    }
    if (url.pathname === "/") {
      return new Response(request.method === "HEAD" ? null : page,{headers:{
        ...common,"content-type":"text/html; charset=utf-8","cache-control":"public, max-age=60",
      }});
    }
    const name = url.pathname.slice("/media/".length);
    if (!url.pathname.startsWith("/media/") || !mediaFiles.has(name)) {
      return new Response(request.method === "HEAD" ? null : "Not found",{status:404,headers:common});
    }
    const upstream = "https://raw.githubusercontent.com/arpit-ae/princess-kanish/" + revision + "/media/" + name;
    const range = request.headers.get("range");
    const response = await fetch(upstream,{method:request.method,headers:range ? {range} : {}});
    if (!response.ok && response.status !== 416) {
      return new Response(request.method === "HEAD" ? null : "Media unavailable",{status:502,headers:common});
    }
    const headers = new Headers(common);
    headers.set("content-type",name.endsWith(".mp4") ? "video/mp4" : "image/webp");
    headers.set("cache-control","public, max-age=86400");
    for (const key of ["accept-ranges","content-range","content-length","etag","last-modified"]) {
      const value = response.headers.get(key);
      if (value) headers.set(key,value);
    }
    return new Response(request.method === "HEAD" ? null : response.body,{status:response.status,headers});
  }
};
